-- ============================================================
-- MULTIEMPRESA (MULTI-TENANT) - ContaPyme
-- Cada registro operativo pertenece a una empresa mediante empresa_id.
-- Los datos que ya existían se asignan a la empresa principal (id=1).
-- ============================================================
DROP TABLE IF EXISTS empresa_modulos CASCADE;
DROP TABLE IF EXISTS empresas CASCADE;

CREATE TABLE empresas (
  id_empresa integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  nombre varchar(120) NOT NULL,
  tipo_negocio varchar(60) DEFAULT NULL,
  activo smallint NOT NULL DEFAULT 1,
  fecha_creacion timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id_empresa)
);

CREATE TABLE empresa_modulos (
  id_empresa integer NOT NULL,
  modulo varchar(60) NOT NULL,
  habilitado boolean NOT NULL DEFAULT TRUE,
  PRIMARY KEY (id_empresa, modulo),
  CONSTRAINT fk_empresa_modulos_empresa
    FOREIGN KEY (id_empresa) REFERENCES empresas (id_empresa) ON DELETE CASCADE
);

-- Conversión de ContaPyme de MySQL 8 a PostgreSQL
-- Ejecutar conectado a la base de datos contapyme ya creada.
-- IMPORTANTE: elimina y recrea las tablas indicadas en este script.


DROP TABLE IF EXISTS bitacora_accesos CASCADE;
CREATE TABLE bitacora_accesos (

  id_bitacora integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  id_usuario integer DEFAULT NULL,
  nombre_usuario varchar(60) DEFAULT NULL,
  accion varchar(100) NOT NULL,
  ip_origen varchar(45) DEFAULT NULL,
  fecha timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  detalle text,
  PRIMARY KEY (id_bitacora)
);

DROP TABLE IF EXISTS categorias CASCADE;
CREATE TABLE categorias (

  id_categoria integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  nombre varchar(80) NOT NULL,
  descripcion text,
  estatus smallint NOT NULL DEFAULT '1' ,
  PRIMARY KEY (id_categoria)
);
CREATE UNIQUE INDEX categorias_nombre ON categorias (nombre);

DROP TABLE IF EXISTS clientes CASCADE;
CREATE TABLE clientes (

  id_cliente integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  nombre_cliente varchar(80) NOT NULL,
  apellido_paterno varchar(80) DEFAULT NULL,
  apellido_materno varchar(80) DEFAULT NULL,
  calle varchar(120) DEFAULT NULL,
  num_exterior varchar(15) DEFAULT NULL,
  colonia varchar(80) DEFAULT NULL,
  codigo_postal varchar(10) DEFAULT NULL,
  ciudad varchar(80) DEFAULT NULL,
  estado varchar(80) DEFAULT NULL,
  telefono varchar(20) DEFAULT NULL,
  correo varchar(120) DEFAULT NULL,
  estatus smallint NOT NULL DEFAULT '1' ,
  fecha_registro timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id_cliente)
);
CREATE INDEX clientes_idx_clientes_estatus ON clientes (estatus);
CREATE INDEX clientes_idx_clientes_ciudad_est ON clientes (ciudad,estado);

DROP TABLE IF EXISTS codigos_2fa CASCADE;
CREATE TABLE codigos_2fa (

  id_codigo integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  id_usuario integer NOT NULL,
  codigo varchar(10) NOT NULL,
  expiracion timestamp NOT NULL,
  usado smallint NOT NULL DEFAULT '0',
  intentos smallint NOT NULL DEFAULT '0',
  fecha_creacion timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id_codigo)
);
CREATE INDEX codigos_2fa_idx_2fa_usuario ON codigos_2fa (id_usuario);

DROP TABLE IF EXISTS compras CASCADE;
CREATE TABLE compras (

  id_compra integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  codigo varchar(30) NOT NULL,
  fecha timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  id_proveedor integer NOT NULL,
  id_usuario integer NOT NULL,
  condiciones_pago varchar(7) NOT NULL,
  fecha_vencimiento date DEFAULT NULL ,
  subtotal decimal(12,2) NOT NULL,
  total decimal(12,2) NOT NULL,
  estatus varchar(14) NOT NULL DEFAULT 'pendiente_pago',
  PRIMARY KEY (id_compra)
);
CREATE UNIQUE INDEX compras_codigo ON compras (codigo);
CREATE INDEX compras_fk_compra_usuario ON compras (id_usuario);
CREATE INDEX compras_idx_compras_proveedor ON compras (id_proveedor);
CREATE INDEX compras_idx_compras_estatus_fecha ON compras (estatus,fecha);

DROP TABLE IF EXISTS cuentas_por_cobrar CASCADE;
CREATE TABLE cuentas_por_cobrar (

  id_cxc integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  id_cliente integer NOT NULL,
  id_venta integer NOT NULL,
  fecha_emision date NOT NULL,
  fecha_vencimiento date NOT NULL,
  monto_original decimal(12,2) NOT NULL,
  saldo_pendiente decimal(12,2) NOT NULL,
  estatus varchar(9) NOT NULL DEFAULT 'pendiente',
  PRIMARY KEY (id_cxc)
);
CREATE UNIQUE INDEX cuentas_por_cobrar_id_venta ON cuentas_por_cobrar (id_venta);
CREATE INDEX cuentas_por_cobrar_idx_cxc_cliente_est ON cuentas_por_cobrar (id_cliente,estatus);
CREATE INDEX cuentas_por_cobrar_idx_cxc_vencimiento ON cuentas_por_cobrar (fecha_vencimiento);

DROP TABLE IF EXISTS cuentas_por_pagar CASCADE;
CREATE TABLE cuentas_por_pagar (

