  estatus varchar(9) NOT NULL DEFAULT 'pendiente',
  PRIMARY KEY (id_cxp)
);
CREATE UNIQUE INDEX cuentas_por_pagar_id_compra ON cuentas_por_pagar (id_compra);
CREATE INDEX cuentas_por_pagar_idx_cxp_proveedor_est ON cuentas_por_pagar (id_proveedor,estatus);
CREATE INDEX cuentas_por_pagar_idx_cxp_vencimiento ON cuentas_por_pagar (fecha_vencimiento);

DROP TABLE IF EXISTS cxc_cobros CASCADE;
CREATE TABLE cxc_cobros (

