  PRIMARY KEY (id_producto)
);
CREATE UNIQUE INDEX productos_codigo ON productos (codigo);
CREATE INDEX productos_idx_productos_estatus ON productos (estatus);
CREATE INDEX productos_idx_productos_tipo ON productos (tipo);
CREATE INDEX productos_idx_productos_categoria ON productos (id_categoria);

DROP TABLE IF EXISTS proveedores CASCADE;
CREATE TABLE proveedores (

  id_proveedor integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  nombre_empresa varchar(120) NOT NULL,
  nombre_contacto varchar(120) DEFAULT NULL,
  telefono varchar(20) DEFAULT NULL,
  correo varchar(120) DEFAULT NULL,
  calle varchar(120) DEFAULT NULL,
  colonia varchar(80) DEFAULT NULL,
  ciudad varchar(80) DEFAULT NULL,
  estado varchar(80) DEFAULT NULL,
  estatus smallint NOT NULL DEFAULT '1' ,
  fecha_creacion timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id_proveedor)
);

DROP TABLE IF EXISTS roles CASCADE;
CREATE TABLE roles (

  id_rol integer NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  nombre varchar(50) NOT NULL,
