  estatus smallint NOT NULL DEFAULT '1' ,
  fecha_creacion timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id_rol)
);
CREATE UNIQUE INDEX roles_nombre ON roles (nombre);

