-- Empresa principal: recibe todos los datos que ya existían en esta instalación.
INSERT INTO empresas (id_empresa, nombre, tipo_negocio, activo) VALUES (1, 'Empresa principal', NULL, 1);
SELECT setval(pg_get_serial_sequence('empresas', 'id_empresa'), COALESCE((SELECT MAX(id_empresa) FROM empresas), 1), TRUE);

