-- Cada código/nombre único se valida dentro de su empresa, no globalmente.
DROP INDEX IF EXISTS categorias_nombre;
CREATE UNIQUE INDEX categorias_nombre_empresa ON categorias (empresa_id, nombre);

DROP INDEX IF EXISTS productos_codigo;
CREATE UNIQUE INDEX productos_codigo_empresa ON productos (empresa_id, codigo);

DROP INDEX IF EXISTS compras_codigo;
