DROP INDEX IF EXISTS usuarios_nombre_usuario;
CREATE UNIQUE INDEX usuarios_nombre_usuario_empresa ON usuarios (empresa_id, nombre_usuario);

DROP INDEX IF EXISTS usuarios_correo;
CREATE UNIQUE INDEX usuarios_correo_empresa ON usuarios (empresa_id, correo);

