DROP VIEW IF EXISTS v_cxc_pendientes CASCADE;
CREATE VIEW v_cxc_pendientes AS
SELECT cxc.empresa_id, cxc.id_cxc, c.nombre_cliente,
       concat(c.apellido_paterno, ' ', COALESCE(c.apellido_materno, '')) AS apellidos,
       cxc.fecha_emision, cxc.fecha_vencimiento, cxc.monto_original,
       cxc.saldo_pendiente, cxc.estatus,
       CASE WHEN cxc.fecha_vencimiento < CURRENT_DATE
                 AND cxc.estatus NOT IN ('saldada', 'cancelada')
            THEN 'VENCIDA' ELSE 'VIGENTE' END AS condicion
FROM cuentas_por_cobrar cxc
JOIN clientes c
  ON c.id_cliente = cxc.id_cliente
 AND c.empresa_id = cxc.empresa_id
WHERE cxc.estatus NOT IN ('saldada', 'cancelada');

DROP VIEW IF EXISTS v_cxp_pendientes CASCADE;
CREATE VIEW v_cxp_pendientes AS
SELECT cxp.empresa_id, cxp.id_cxp, p.nombre_empresa,
       cxp.fecha_emision, cxp.fecha_vencimiento, cxp.monto_original,
       cxp.saldo_pendiente, cxp.estatus,
       CASE WHEN cxp.fecha_vencimiento < CURRENT_DATE
                 AND cxp.estatus NOT IN ('saldada', 'cancelada')
            THEN 'VENCIDA' ELSE 'VIGENTE' END AS condicion
FROM cuentas_por_pagar cxp
JOIN proveedores p
  ON p.id_proveedor = cxp.id_proveedor
 AND p.empresa_id = cxp.empresa_id
WHERE cxp.estatus NOT IN ('saldada', 'cancelada');

DROP VIEW IF EXISTS v_saldo_caja CASCADE;
CREATE VIEW v_saldo_caja AS
SELECT empresa_id,
       SUM(CASE WHEN tipo = 'entrada' THEN monto ELSE -monto END) AS saldo_actual,
       COUNT(*) AS total_movimientos
FROM movimientos_caja
GROUP BY empresa_id;

DROP VIEW IF EXISTS v_stock_bajo CASCADE;
CREATE VIEW v_stock_bajo AS
SELECT p.empresa_id, p.id_producto, p.codigo, p.nombre,
       p.stock AS existencia_actual, p.stock_minimo, c.nombre AS categoria
FROM productos p
JOIN categorias c
  ON c.id_categoria = p.id_categoria
 AND c.empresa_id = p.empresa_id
WHERE p.tipo = 'producto'
  AND p.estatus = 1
  AND p.stock <= p.stock_minimo;



-- ============================================================
-- NOTAS DE IMPLEMENTACIÓN MULTIEMPRESA
-- 1) Este archivo es un script de instalación/reconstrucción: contiene DROP TABLE.
--    No ejecutarlo sobre producción sin respaldo y sin validar el procedimiento.
-- 2) Los registros originales quedan en empresa_id = 1.
-- 3) El backend debe obtener empresa_id desde la sesión/token autenticado,
--    nunca confiar en un empresa_id enviado libremente por el navegador.
-- 4) TODAS las consultas SELECT/INSERT/UPDATE/DELETE deben limitarse por empresa_id.
-- 5) Al insertar detalles/transacciones, validar que sus referencias (producto,
--    cliente, proveedor, venta, compra, etc.) pertenezcan a la misma empresa.
-- 6) empresa_modulos permite configurar módulos visibles por empresa; la aplicación
--    debe consultar esta tabla para ocultar/mostrar funciones.
-- 7) roles se conserva como catálogo global de permisos. Si cada empresa requiere
--    roles personalizados, deberá evolucionarse su diseño.
-- 8) Las vistas ahora incluyen empresa_id (y saldo de caja se agrupa por empresa).
-- ============================================================
